_formatToCharacterIterator() {
        MessageFormat format = new MessageFormat("{0,number,#.##}");
        Object[] arguments = new Object[] { new Integer(1) };
        Object result = format.formatToCharacterIterator(arguments);
        assertThat(result, is(instanceOf(CharacterIterator.class)));
        CharacterIterator it = (CharacterIterator) result;
        assertEquals("1", it.current());
        assertEquals(1, it.getIndex());
    }

